package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import net.minecraft.nbt.*;
/** Source saves, including actual vanilla item NBT merge, define the safe empty-reader boundary. */
public final class ScreenOwnershipChecks {
 public static void main(String[] args)throws Exception{JsonObject source;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenOwnershipReference")))){source=JsonParser.parseReader(reader).getAsJsonObject();}int cases=0;for(var row:source.getAsJsonArray("cases")){var expected=row.getAsJsonObject();CompoundTag tag=new CompoundTag();String reader=expected.get("savedReader").getAsString();if(!reader.equals("absent"))tag.put("ScreenChipReader",TagParser.parseTag(reader));if(expected.get("selected").getAsBoolean())tag.putInt("PrimarySurfaceTexture",-4);boolean installable=expected.get("kind").getAsInt()<4;CompoundTag original=tag.copy();if(NativeScreenOwnership.installable(tag)!=installable||!original.equals(tag))throw new AssertionError("Source reader guard differs "+expected);cases++;}CompoundTag canonical=new CompoundTag();canonical.put("ScreenChipReader",TagParser.parseTag(source.get("emptyReader").getAsString()));if(!NativeScreenOwnership.installable(canonical))throw new AssertionError("Actual Source empty reader rejected");canonical.getCompound("ScreenChipReader").putString("FutureOwner","opaque");if(NativeScreenOwnership.installable(canonical))throw new AssertionError("Unknown ownership accepted");if(cases!=42||!source.get("sha256").getAsString().equals("bf63f918fdc6764207efe6d9182820b879110e2d0e021d70f8fa598d8d0ea72f"))throw new AssertionError("Source ownership coverage changed");System.out.println("Native Screen ownership boundary PASS Source constructor/allocation/item saves="+cases);}
}
